python3 -c "
import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_2/projects/ratekv/registry.yaml') as f:
    data = yaml.safe_load(f)
exps = data.get('experiments', {})
# Check Gemma-2 and Qwen sweep status
for eid in ['gemma2_hires_bf16_2bitonly', 'w3_downstream_eval', 'qwen_compounding_sweep_v2']:
    if eid in exps:
        e = exps[eid]
        print(f'{eid}: status={e.get(\"status\")}, conclusion={e.get(\"conclusion\")}')
        spec = e.get('spec', {})
        if 'command' in spec:
            print(f'  cmd: {spec[\"command\"][:120]}')
    else:
        print(f'{eid}: NOT FOUND')
# Find any gemma downstream
for eid in exps:
    if 'gemma' in eid.lower() and 'downstream' in eid.lower():
        print(f'  Gemma downstream: {eid}: status={exps[eid].get(\"status\")}, conclusion={exps[eid].get(\"conclusion\")}')
"
